INSERT INTO `person` VALUES (5,'card17.tpl','Елена','Колесникова','','Александровна','','1983-01-07','2006-08-11','<p>Колесникова Елена Александровна родилась 7 декабря 1983 года, в городе Томске. Окончила среднюю школу №4, затем училась в Политехническом Университете на ГГФ, на геолога. Окончила&nbsp; университет в 2005 году, затем работала менеджером в небольшой фирме по разработке и сопровождению сайтов, в частности работала над сайтом life.tomsk.ru. Злополучным летом 2006-го активно занималась поисками новой работы, по специальности.<br />Бронхиальной астмой болела с детства, но ее мама заботилась о здоровье своего ребенка. Задавить болезнь помогли активный образ жизни и закаливания холодной водой, задавить, но не победить. В&nbsp; клуб пришла в 2003г на отделение РТФСУ. Лена очень жизнерадостный человек, легкий в общении c чрезвычайно заразительным смехом. Любой человек легко мог узнать ее по смеху,даже если всего лишь раз&nbsp; слышал его раньше.<br />Участница &laquo;Оранжевого настроения&raquo; (концерт авторской песни) и актриса театра &laquo;Оксюморон&raquo;. Сыгранные роли: Наивная, но счастливая &laquo;блондинка&raquo; Лена в спектакле <a title=\"2005-Аспарагус\" href=\"http://oxymoron.tomsk.ru/all/2005-Asparagus/Video/2005_Asparagus.wmv\" target=\"_blank\">&laquo;Аспарагус или чего хотят женщины&raquo; 2005г&nbsp;</a> и девушка &ndash; ангел по имени Анжела в <a title=\"2006-Спорим\" href=\"http://oxymoron.tomsk.ru/all/2006-Sporim/Video/2006_Sporim.avi\" target=\"_blank\">&laquo;Спорим?!&raquo; 2006г&nbsp;</a> <br />В горные походы Лена так и не успела сходить, хотя очень хотела. Была только на Малой Сые в &laquo;Ящике Пандоры&raquo;, ещё на Ергаках в 2005м. и водные походы по Алчедату, Яе, Золотому Китату.<br />Лены не стало 11 августа 2006г. в связи с осложнением основного заболевания.</p>','http://inmemoria.tusur.ru/media/20120704103116.jpg','http://inmemoria.tusur.ru/media/20120704103116s.jpg',1),(3,'card4.tpl','Елена','Бикмулина','','Олеговна','','1983-01-15','2004-03-29','<p>Бикмулина Елена Олеговна на родилась 15.01.1983г. в г.Асино Томской области.<br />В 1999г. поступила в СГМУ на лечебный факультет.<br />В клуб пришла весной 2000г. на отделение РТФСУ.<br />Поражала разносторонностью интересов и широким кругозором. Медицина-медициной, а душа тянулась к истории, литературе и прочей гуманитарии. В последние годы увлеклась журналистикой. А еще Ленка рисовала, интересно и необычно. И писала стихи, жаль редко записывала на бумаге, а сколько она их знала наизусть и сколько прочитала книг. С ее легкой руки в клубе тогда появились поэтические вечера при свечах. У нее потрясающее чувство юмора и удивительная способность называть вещи своими именами, уж как есть&hellip;<br />Кто был с ней в походах, знает, какой она неунывающий, веселый, открытый, надежный человек, \"наш\" человек.<br />За плечами у Лены пара горных походов и несколько водных. <br />Лены не стало 29.03.2004г. в реанимации НИИ кардиологии после операции на сердце.</p>','http://inmemoria.tusur.ru/media/20120704102731.jpg','http://inmemoria.tusur.ru/media/20120704102731s.jpg',1),(6,'card19.tpl','Алексей','Толстик','Беспалов','Валерьевич','Банкир','1978-08-07','2008-08-06','<p>Беспалов Алексей Валерьевич родился 7 августа 1978 году в Казахстане, пос.Панфилов, Алматинская область. В 1995 году поступил в ТУСУР, на Радио-Конструкторский факультет (РКФ), но не окончил его. Увлекался туризмом, занимался в клубе \"Наяда\" (ТУСУР) и клубе ТАКТ (отделение ФЭТ, ТУСУР). В горном походе по Джунгарскому Алатау под руководством А.А.Смолина (1 к.с.) в 1998г. приобрел прозвище \"Банкир\". После женитьбы на Оксане Александровне Толстик 06.10.2000г. , сменил фамилию на Толстик. Есть дочь - Толстик Евгения Алексеевна. Работал в ЗАО \"Сибремсервис\",г.Томск.<br />Скончался 6 августа 2008 года в Томске, осложнения после операции (онкология).</p>','http://inmemoria.tusur.ru/media/20120621165833.jpg','http://inmemoria.tusur.ru/media/20120621165833s.jpg',1),(7,'card1.tpl','Борис','Агалаков','','Александрович','','1945-11-30','2008-01-20','<p>Агалаков Борис Анатольевич родился в 1945г. В 1969г закончил ТИРиЭТ (РТФ). Годы в клубе: 1964-1969гг.<br />Обладатель жетона &laquo;Ветеран ТАКТ&raquo; второй степени,&nbsp;1 спортивный разряд по альпинизму, по туризму, по спортивному ориентированию, инструктор по горному туризму, офицер СА.</p>\r\n<p>&nbsp;</p>','http://inmemoria.tusur.ru/media/20120621170024.jpg','http://inmemoria.tusur.ru/media/20120621170024s.jpg',1),(8,'card3.tpl','Юрий','Белов','','Викторович','','1968-03-21','1989-08-12','<p>Белов Юрий Викторович<br />Родился 21.03.1968г.<br />Пришел в клуб 1985г.<br />Погиб 12 августа 1989г. при руководстве походом 2к.с. на Терскей Алатоо в составе летних туристских сборов ТАКТа. Непосредственной причиной смерти явилось падение в трещину и длительное пребывание на веревке в трещине.</p>','http://inmemoria.tusur.ru/media/20120621170307.jpg','http://inmemoria.tusur.ru/media/20120621170307s.jpg',1),(9,'card12.tpl','Дмитрий','Пичугин','','Владимирович','','1979-10-30','2011-08-02','<p>Пичугин Дмитрий Владимирович родился 30 октября 1979г. в Петропавловске (Казахстан), из-за работы родителей часть детства провел в Алжире. <br />В Томске учился в 40-й школе. В 1996 году, после школы, поступил в ТПУ на факультет АВТФ, кафедру ОСУ. После окончания ВУЗа в 2002 году поступил в аспирантуру. Защитил кандидатскую диссертацию, при этом совмещая аспирантуру с работой. Работал web-программистом, как в сторонних компаниях, так и в своей, в рамках которой реализовывал проекты для иностранных заказчиков. С английским всегда было отлично, и со своими \"заказчиками\" не только работал, но и дружил.<br />В ТАКТ пришел в 2001 году, на отделение РТФСУ, после того, как сходил летом на Алтай с коммерческой группой. Поход был по Аккему, в том числе с восхождением на Белуху. Необычный был новичок - побывавший на Белухе. Впоследствии у Димы была очень обширная походография, но Аккем, Белуха всегда оставались любимыми местами. Сюда он потом повел первый поход под своим руководством.<br />Увлекался сноубордом - начинал кататься в Академе, очень любил Шерегеш. Позднее в увлечениях появился велосипед и велопоходы. Из хобби еще нужно выделить фотографию &ndash; сначала это было простое фотографирование в походах на цифровые мыльницы, потом переросло во что-то большее. И техника стала другая, и сами фотографии вышли на другой уровень. Фотографии размещал на сайтах:<br /><a href=\"http://mountain.35photo.ru/\" target=\"_blank\">http://mountain.35photo.ru/</a></p>\r\n<p><a href=\"http://www.photosight.ru/users/147831/\" target=\"_blank\">http://www.photosight.ru/users/147831/&nbsp;</a></p>\r\n<p>В 2007г переехал в Санкт-Петербург, в 2008-2009гг. жил и работал в Финляндии, в сентябре 2009г. вернулся в Питер, продолжая работать в финской компании.<br />Женат, есть сын Владимир 2009 года рождения.<br /><br />Еще Дима постоянно мечтал о Памире&hellip;<br />2 августа 2011 г. погиб при восхождении на пик Крупской, в горном походе 5 к.с. по Памиру.</p>\r\n<p>&nbsp;</p>','http://inmemoria.tusur.ru/media/20120621165021.jpg','http://inmemoria.tusur.ru/media/20120621165021s.jpg',1),(10,'card18.tpl','Вячеслав','Коломин','','Юрьевич','','1970-06-22','2002-01-08','<p>Коломин Вячеслав Юрьевич родился 22.06.1970г. <br />Член клуба ТАКТ с 1990 года, кандидат в мастера спорта по альпинизму, врач сибирской экспедиции на Эверест 2001 года, сотрудник НИИ кардиологии.<br />Занимался научной работой в том числе и в горах. Заканчивал работу над кандидатскую диссертацией о длительном воздействии высоты на работу сердца. Очень мягкий, добрый и светлый человек.<br />Погиб 8 января 2002 года на спуске с вершины Караташ по маршруту 2А к.с.(Алтай, Ак-Тру), в результате схода лавины</p>\r\n<p><a title=\"Подробности гибели Славы\" href=\"http://takt.tusur.ru/about/memorial/podrob.php\" target=\"_blank\">Подробности гибели Славы</a></p>\r\n<p>&nbsp;</p>','http://inmemoria.tusur.ru/media/20121120205923.jpg','http://inmemoria.tusur.ru/media/20121120205923s.jpg',1),(11,'card7.tpl','Николай','Ветошкин','','Викторович','','1951-05-31','1984-02-01','<p>Ветошкин Николай Викторович родился 31 мая 1951г. Закончил Томский&nbsp; институт автоматизированных систем управления и радиоэлектроники (ТИАСУР) , Факультет электронной техники (ФЭТ) в 1979г. по специальности \"Промышленная электроника\"<br />&laquo;Ветеран ТАКТ&raquo;. Жетон № 62<br />&nbsp;2+ разряд по альпинизму,&nbsp; инструктор горного туризма.<br />Выполнял обязанности Босса на ФЭТ (примерно в период с 1976 по 1977г )<br />Умер 3 февраля 1984г.(онкология)</p>\r\n<p>&nbsp;</p>','http://inmemoria.tusur.ru/media/20120704102300.jpg','http://inmemoria.tusur.ru/media/20120704102300s.jpg',1),(12,'card16.tpl','Григорий','Каспирович','','Ефимович','','1940-11-05','1991-09-26','<p>Каспирович Григорий Ефимович родился 5.11.1940г. В 1962г. окончил Томский политехнический институт, радиотехнический факультет. По распределению уехал в г.Новосибирск и работал на предприятиях электронной промышленности. Долгое время был начальником отдела Сибирского научно-исследовательского института авиации.<br />В студенческие годы стал увлекаться спортивным туризмом. В 1959 году, будучи студентом третьего курса, принял участие в одном из первых горных походов на Западный Тянь-Шань (руководитель Иванов Г.Н.). В Новосибирске Григорий увлекся спортивным ориентированием и альпинизмом. Он был очень способным и целеустремленным спортсменом. Первым из спортсменов Западной Сибири получил звание мастера спорта по спортивному ориентированию, а затем и мастера спорта по альпинизму.<br />Григорий Ефимович ушел из жизни 26.09.1991г.</p>','http://inmemoria.tusur.ru/media/20120625234213.jpg','http://inmemoria.tusur.ru/media/20120625234213s.jpg',1),(21,'card6.tpl','Андрей','Бурков','','Владимирович','','1990-02-16','2012-08-09','<p>Родился 16 февраля 1990г.</p>\r\n<p>Учился в школе №9, во время учебы завоевал I место в конкурсе \"Энергия будущего\", который проводился СХК в 2006г. Номинация № 4: \"Тайны атомного ядра и материи.\"Применение достижений ядерной науки, техники и технологий(&laquo;Научно-технический блок&raquo;) - работа \"Холодный ядерный синтез\" (<a href=\"http://www.atomsib.ru/sci/museum/competitions/Energy_of_the_future/2006/Pobediteli.html\" target=\"_blank\">ссылка</a>).</p>\r\n<p>После окончания школы посупил в ТУСУР на Радиотехнический факультет (РТФ), на кафедру Радиоэлектроники и защиты информации (РЗИ).</p>\r\n<p>В Клубе с 2010г, отделение РТФ. Полиатлонист, лыжник, увлекался велоспортом.<br />Многократный главный судья соревнований по лыжным гонкам клуба ТАКТ и традиционного Осеннего кросса ТАКТ. Неоднократный победитель и призер Осеннего кросса и соревнований по лыжным гонкам клуба ТАКТ (<a href=\"http://takt.tomsk.ru/db/web.page?pid=19245\" target=\"_blank\">ссылка</a>).</p>\r\n<p>Участник команды ТАКТа на Всероссийских соревнованиях по ПСР в Сочи в марте 2012г.</p>\r\n<p>Участник Осеннего марафона \"Берендеи - 2011\". 3-й этап Кубка СФО (Сибирского федерального округа) по спортивному туризму &laquo;Экстрим-Поход&raquo; (<a href=\"http://www.marshruty.ru/Meetings/Meeting.aspx?MeetingID=e0979850-83b8-4d44-a3c0-b245ab6a0555\" target=\"_blank\">ссылка1</a>, <a href=\"http://berendei.tsu.ru/?p=1832\" target=\"_blank\">ссылка2</a>)</p>\r\n<p>В июне 2012 году участвовал в фотоконкурсе \"Комсомольской правды\" - \"Я из Томска \" (<a href=\"http://www.kp.ru/contest/yaiztomska/6/\" target=\"_blank\">ссылка1</a>, <a href=\"http://www.kp.ru/daily/forumcontest/photo/109397\" target=\"_blank\">ссылка2</a>).</p>\r\n<p>В июле 2012г. на альпсборах ТАКТ в ущелье Ала-Арча, Киргизский хребет при восхождении на пик Рацека по маршруту 2Б в результате камнепада и падения вниз по склону получил серьезные травмы спины. Был эвакуирован в Бишкек и далее Москву, но, не смотря на проведенные медицинские мероприятия, 9 августа 2012г. Андрея не стало.</p>','http://inmemoria.tusur.ru/media/20120908094159.jpg','http://inmemoria.tusur.ru/media/20120908094159s.jpg',1),(13,'card5.tpl','Ольга','Бочарова','','Петровна','','1956-11-30','1980-01-01','<p>Бочарова Ольга Петровна.</p>\r\n<p>Годы учебы: 1974-1979гг. ТИРиЭТ (КТФ).</p>\r\n<p>Погибла в 1980г. в походе с красноярцами</p>','http://inmemoria.tusur.ru/media/20120819003608.jpg','http://inmemoria.tusur.ru/media/20120819003608s.jpg',1),(14,'card11.tpl','Николай','Денисов','','Прокопьевич','','1941-01-01','2002-01-01','<p>Денисов Николай Прокопьевич</p>\r\n<p>год рождения - 1941г.&nbsp;</p>\r\n<p>РТФ ТИРиЭТ, год выпуска 1963-й,</p>\r\n<p>жетон &laquo;Ветеран ТАКТ&raquo; № 7 третьей степени, 1 спортивный разряд по туризму, 2 спортивный разряд по альпинизму, спортивному ориентированию, инструктор по горному туризму.</p>\r\n<p>Председатель секции ТиА ТИРиЭТа 1966-1967гг.</p>\r\n<p>Председатель МКК ТИРиЭТа 1968-1969гг.</p>\r\n<p>Кандидат технических наук, доцент</p>\r\n<p>Николай Прокопьевич ушел из жизни в 2002г</p>','http://inmemoria.tusur.ru/media/20120828235925.jpg','http://inmemoria.tusur.ru/media/20120828235925s.jpg',1),(15,'card12.tpl','Николай','Дорогин','','Николаевич','','1944-01-01','2010-01-01','<p>Дорогин Николай Николаевич родился в 1944г.</p>\r\n<p>КТФ ТИРиЭТ, год выпуска 1967-й,</p>\r\n<p>Обладатель жетона &laquo;Ветеран ТАКТ&raquo; № 22 третьей степени.&nbsp;</p>\r\n<p>После окончания института жил и работал в Бийске, затем &ndash; Преподаватель школы в пос. Сычёвка.&nbsp;</p>\r\n<p>Николай Николаевич ушел из жизни в 2010г.</p>','http://inmemoria.tusur.ru/media/20120828235632.jpg','http://inmemoria.tusur.ru/media/20120828235632s.jpg',1),(16,'card2.tpl','Нина','Арцимович','Панова','Антоновна','','0000-00-00','0000-00-00','<p>Арцимович (Панова) Нина Антоновна окончила институт в 1968г. Затем работала на заводе в Омске. В 1967г. ездила в альплагерь по путевке ТАКТа. &nbsp;В Омске продолжала заниматься туризмом</p>','http://inmemoria.tusur.ru/media/20120923214517.jpg','http://inmemoria.tusur.ru/media/20120923214517s.jpg',1),(17,'card8.tpl','Владимир','Герасименко','','Викторович','','1966-01-16','1986-11-30','<p>Родился 16 января 1966г. Закончил школу в Южно-Сахалинске и поступил в ТАСУР на РТФ в 1983г. В этом же году пришел в клуб.</p>\r\n<p>Володя умер от онкологии в 20 лет.</p>\r\n<p>С 1986г. ТАКТовские соревнования по спасательным работам в горах посвящены памяти Владимира Герасименко</p>','http://inmemoria.tusur.ru/media/20120726174332.jpg','http://inmemoria.tusur.ru/media/20120726174332s.jpg',1),(18,'card9.tpl','Валерий','Горпинюк','','Федорович','','1949-08-04','2001-08-18','<p>Горпинюк Валерий Федорович родился &nbsp;4 августа 1949г. в городе Майли-Сай Ошской обл. &nbsp;В 1966 году с золотой медалью закончил школу и поступил в ТИРиЭТ на РТФ. В годы учебы в институте был активным членом ТАКТа, участвовал в соревнованиях, походах и горовосхождениях. По окончании института в 1971 году был призван в СА, служил в Ленинске. После службы в армии вернулся в Майли-Сай. &nbsp;В 1993 году с семьей переехал в Россию в п.Калашниково, Тверской обл.&nbsp;Вместе с женой Раей (Черепановой) воспитал троих замечательных детей.</p>\r\n<p>Валерий умер 18 августа 2001г.</p>','http://inmemoria.tusur.ru/media/20120915181437.jpg','http://inmemoria.tusur.ru/media/20120915181437s.jpg',1),(19,'card13.tpl','Александр','Заяц','','Николаевич','','1955-08-13','2011-05-09','<p>Родился 13 августа 1955г.</p>\r\n<p>Годы в клубе: с 1972 по 1986гг.</p>\r\n<p>Умер 9 мая 2011г. после продолжительной болезни.</p>','http://inmemoria.tusur.ru/media/20120924225006.jpg','http://inmemoria.tusur.ru/media/20120924225006s.jpg',1),(20,'card14.tpl','Александр','Зернов','','Александрович','','1943-01-01','2007-07-05','<p>Зернов Александр Александрович родился 1 января 1943. в 1967г. окончил ТИРиЭТ, ФЭТ специальность: диэлектрики и полупроводники. Обладатель жетона \"Ветеран ТАКТ\" 3-й степени. Второй разряд по альпинизму, горному туризму, инструктор по горному туризму. Один из организаторов первого Пивного слета.&nbsp;В Институте ядерной физики (г Алматы), будучи СНС, работал в лаб-рии Масспектроскопии, сам разработал масспектрогаф. В последние годы там же был главным инженером Лаборатории низкофоновых излучений.В промежутке между периодами работы в ИЯФе работал в Центральной геологопоисковой экспедиции, затем в Гидрометцентре Главным инженером одной из лабораторий.&nbsp;</p>\r\n<p>Умер 5 июля 2007г.</p>','http://inmemoria.tusur.ru/media/20120730231119.jpg','http://inmemoria.tusur.ru/media/20120730231119s.jpg',1),(22,'card4.tpl','Валентина','Лозинская','','Владиславовна','','0000-00-00','0000-00-00','<p>Годы в клубе: 1966-1970гг.</p>','http://inmemoria.tusur.ru/media/20120827001603.jpg','http://inmemoria.tusur.ru/media/20120827001603s.jpg',1),(23,'card5.tpl','Антон','Майер','','Рохусович','','1951-11-30','2008-03-07','<p>Майер Антон Рохусович родился в 1952г. Пришел в клуб в 1971г. Он был очень ярким человеком, лидером в ТАКТе на протяжении, как минимум, 10-ти лет. Занимался всеми направлениями, которые были в клубе: спелео, альпинизм, скалолазание, водный, лыжные пробеги, горный туризм. Всегда был организатором и руководителем. Водил горные походы высокой категории сложности, в том числе был и зимний поход 5к.с. в район Куйлю. Все его начинания и дела &nbsp;очень значительны.&nbsp;Он жил в ТАКТе и ТАКТ любил его.</p>\r\n<p>Обладатель жетона \"Ветеран ТАКТ\" 3 степени.</p>\r\n<p>Антон умер 7 марта 2008г.</p>\r\n<p>&nbsp;</p>','http://inmemoria.tusur.ru/media/20120815225853.jpg','http://inmemoria.tusur.ru/media/20120815225853s.jpg',1),(24,'card6.tpl','Валентин','Мащенко','','Григорьевич','Волька','1940-04-10','1986-08-25','<p>Мащенко Валентин Григорьевич (для всех - Волька) родился 10 апреля 1940г. В 1967г. окончил КТФ ТИРиЭТ, специальность \"Диэлектрики и полупроводники\". Начиная с последних курсов работал в ТИРиЭТе &nbsp;(ТУСУРе) на кафедре СВЧ, Лаборатория роста кристаллов (1967 &ndash; 1973гг.). Затем уехал в Красноярск.</p>\r\n<p>жетон &laquo;Ветеран ТАКТ&raquo; № 21 третьей степени, 2 спортивный разряд по альпинизму, младший инструктор по &nbsp;туризму.</p>\r\n<p>Босс ФЭТа 1965-1966гг. Босс РУФ/КТФ 1966-1967гг.</p>\r\n<p>Умер 25 августа 1986г. в г.Красноярске</p>\r\n<div>&nbsp;</div>','http://inmemoria.tusur.ru/media/20120917174518.jpg','http://inmemoria.tusur.ru/media/20120917174518s.jpg',1),(25,'card8.tpl','Виктор','Мягков','','Алексеевич','','1953-11-30','0000-00-00','<p>Год рождения: 1953г.</p>','http://inmemoria.tusur.ru/media/20120818235831.jpg','http://inmemoria.tusur.ru/media/20120818235831s.jpg',1),(26,'card9.tpl','Нина','Паршина','Германчук','Владимировна','','1959-12-23','2008-06-28','<p>Паршина Нина Владимировна родилась 23 декабря 1959г.</p>\r\n<p>Обладатель жетона \"Ветеран ТАКТ\" 3 степени.</p>\r\n<p>28 июня 2008г. утонула в р.Обь, спасая другого человека</p>','http://inmemoria.tusur.ru/media/20120821231126.jpg','http://inmemoria.tusur.ru/media/20120821231126s.jpg',1),(27,'card13.tpl','Олег ','Руколеев','','Станиславович','','1964-11-30','2004-06-15','<p>Руколеев Олег Станиславович родился в 1965г. В клубе с 1982г (ФЭТ). Обладатель жетона \"Ветеран ТАКТ\" 3 степени. Бесконечный оптимист, большой любитель авторсой песни.</p>\r\n<p>Погиб 15 июня 2004г. в результате несчастного случая на производстве</p>','http://inmemoria.tusur.ru/media/20120826233254.jpg','http://inmemoria.tusur.ru/media/20120826233254s.jpg',1),(28,'card10.tpl','Феликс ','Перегудов','','Иванович','','1931-01-20','1990-12-30','<p>Перегудов Феликс Иванович родился 20 января 1931 года в г. Борисоглебске Воронежской области. Среднюю школу окончил в г. Новосибирске с золотой медалью в 1948 году. В 1948&mdash;1953гг. учился на радиотехническом факультете Томского политехнического института, получил диплом с отличием.</p>\r\n<p>Аспирант, преподаватель ТПИ (1953&ndash;1961гг.), начальник конструкторско &mdash; технологического бюро &laquo;Проект&raquo; (1961&ndash;1966гг.), директор крупного оборонного предприятия &mdash; Томского радиотехнического завода (1966&ndash;1970гг.), заместитель директора, директор НИИ АЭМ при Томском институте автоматизированных систем управления и радиоэлектроники (1970&ndash;1983гг.), ректор ТИАСУРа (1981&ndash;1983гг.), заместитель министра высшего и среднего специального образования РСФСР (1983&ndash;1985гг.), заместитель председателя Госкомитета СССР по образованию, министр СССР (1985&ndash;1990гг.).</p>\r\n<p>Кандидат технических наук &mdash; 1959г., доцент &mdash; 1964г., доктор технических наук &mdash; 1980г., профессор &mdash; 1981г., действительный член (учредитель)Инженерной Академии СССР &mdash; 1990г.</p>\r\n<p>По инициативе Ф.И. Перегудова в 1990 году в Томске был открыт первый в стране \"Технопарк\", явившийся новой рыночной формой региональной интеграции науки, образования, производства и предпринимательства.</p>\r\n<p>Внезапная смерть прервала его работу по осуществлению ряда актуальных образовательных и научных проектов. Умер Феликс Иванович на ходу &ndash; в поезде Ленинград-Москва 30 декабря 1990 года.</p>\r\n<p>В ноябре 1996г. создан Фонд Перегудова,которыйт инициирует и оказывает содействие в реализации социально значимых производственных, инженерно-технических и образовательных проектов в условиях развития рыночных механизмов и отношений. Задачи фонда: помогать талантливым студентам, аспирантам, молодым ученым и специалистам; поддерживать ученых-ветеранов; заниматься изданием научной и учебной литературы, проводить конференции и осуществлять другие мероприятия.</p>\r\n<p><a title=\"http://www.peregudov.ru/peregudov.html\" href=\"http://www.peregudov.ru/peregudov.html\" target=\"_blank\">http://www.peregudov.ru/peregudov.html</a></p>\r\n<p>За выдающиеся заслуги перед Томской областью и в связи с 400-летием Томска Феликсу Ивановичу Перегудову бывшему ректору ТИАСУРа присвоено почетное звание \"Почетный гражданин Томской области\" (посмертно).</p>','http://inmemoria.tusur.ru/media/20120827233937.jpg','http://inmemoria.tusur.ru/media/20120827233937s.jpg',1),(29,'card14.tpl','Ольга ','Сафарова','Леконцева','Владимировна','','0000-00-00','0000-00-00','<p>годы в клубе 1972-1977</p>\r\n<p>Ушла из жизни в 2007г.</p>','http://inmemoria.tusur.ru/media/20120828223141.jpg','http://inmemoria.tusur.ru/media/20120828223141s.jpg',1),(31,'card16.tpl','Владимир','Солобоев','','Евгеньевич','','1953-11-25','1995-07-28','<p>Солобоев Владимир Евгеньевич родился 25 ноября 1953г. В 1973г. окончил ТИРиЭТ(ФЭТиА). Обладатель жетона \"Ветеран ТАКТ\" 3 степени. \"Снежный барс\" (год выполнения - 1988), КМС.</p>\r\n<p>28 июля 1995г. погиб в районе пика Победы (хребет Каинды 5445м) при проведении поисково-спасательных работ.</p>','http://inmemoria.tusur.ru/media/20120905121432.jpg','http://inmemoria.tusur.ru/media/20120905121432s.jpg',1),(30,'card15.tpl','Михаил','Седунов','','Григорьевич','','1951-09-05','1992-02-02','<p>Седунов Михаил Григорьевич родился 5 сентября 1951г. В 1975г. окончил ТИРиЭТ, РТФ по специальности \"Электронные устройства\". Годы в клубе 1969-1976. в 1972-73гг. босс РТФ. С 1973-1976г. президент клуба. Обладатель жетона \"Ветеран ТАКТ\" 3-й степени. 2-й разряд по альпинизму, горному туризму, 3-й разряд по скалолазанию, инструктор по горному туризму.</p>\r\n<p>Умер 2 февраля 1992г.</p>','http://inmemoria.tusur.ru/media/20120828233500.jpg','http://inmemoria.tusur.ru/media/20120828233500s.jpg',1),(32,'card17.tpl','Борис','Соустин','','Порфирьевич','','1933-04-27','2001-03-31','<p>Соустин Борис Порфирьевич родился 27.04.1933г. в г. Топки Кемеровской области. &nbsp;</p>\r\n<p>В 1956г. окончил Томский политехнический институт &nbsp;по специальности \"Электрификация промышленных предприятий\".&nbsp;</p>\r\n<p>С 1956-1960гг. - &nbsp;научный сотрудник НИИ ядерной физики и автоматики в г.Томске.</p>\r\n<p>В 1960г. &nbsp;поступил в целевую аспирантуру Института авиационного приборостроения в г.Ленинграде.&nbsp;</p>\r\n<p>С 1964-1969гг. - старший преподаватель, доцент Томского политехнического института. &nbsp;Кандидатскую диссертацию защитил в 1965 году, докторскую в 1975г.&nbsp;</p>\r\n<p>В &nbsp;1969-1975гг. - заведующий отделом НИИ автоматики и электромеханики в г.Томске;&nbsp;</p>\r\n<p>С 1975 года заведующий кафедрой в Красноярском политехническом институте, декан и директор НИИ информатики и процессов управления, Заслуженный деятель науки и техники РФ.</p>\r\n<p>Соустин Б.П. имел благодарности в приказах МВ и ССО РСФСР, Госкомвуза СССР, ТПИ, НИИ, ТИАСУР, КГТУ, звание Заслуженный деятель науки и техники РСФСР (1990г.), награжден золотой медалью С.П.Королева, избран действительным членом в две общественные Российские Академии наук: Академия Технологических и Электротехнических Наук и Международную Академию Наук Высшей Школы.&nbsp;</p>\r\n<p>Дважды награжден медалями Федерации космонавтики России (им. С.П. Королева и им. В.Ф. Решетнева). Опубликовал более 250 научных работ, в т.ч. 10 монографий, более 50 изобретений.&nbsp;</p>\r\n<p>Основные научные интересы: разработка теоретических основ и проведение исследований в области управления сложными системами, конкретно подсистем космических аппаратов, создание систем поддержки принятия решений при управлении организационной (административной) структурой.</p>\r\n<p>Первое восхождение &ndash; 1953г., последние &ndash; 1999г. &nbsp;Инструктор с 1957г., проработал 6 сезонов. МС СССР &ndash; 1963г.&nbsp;</p>\r\n<p>Чемпион СССР по альпинизму (1960г.) в классе высотных восхождений, серебряный призер (1962г.), бронзовый (1961г.). Восхождения на пики Революции, Таджикистан, К. Маркса. МС СССР (1963г.). С 1960 г. по 1963г. в сборной г.Ленинграда. С 1964 г. по 1968 г. в сборной СССР. &nbsp;13 восхождений на пик В.И. Ленина.&nbsp;</p>\r\n<p>В 1967г. участвовал в операции десантирования на пик Ленина (7134м.), за что был награжден медалью &laquo;За отвагу&raquo;.</p>\r\n<p>Соустин Б.П. принимал активное участие в деятельности клуба самодеятельной песни в Томском политехническом институте. Ему удалось организовать в 70-х годах выступления в Красноярске Юрия Кукина, Евгения Клячкина, Юрия Визбора, Бориса Вахнюка и др. исполнителей авторской песни.</p>\r\n<p>31 марта 2001г. Борис Порфирьевич скончался.</p>\r\n<div>&nbsp;</div>','http://inmemoria.tusur.ru/media/20120906113056.jpg','http://inmemoria.tusur.ru/media/20120906113056s.jpg',1),(35,'card7.tpl','Александр','Шалаев','','Владимирович','','1955-05-03','1999-02-19','<p>Шалаев Александр Владимирович родился 3 мая 1955г. Пришёл в ТАКТ в 1974г. и сразу стал активным участником всех мероприятий клуба. В 1978 г. Александр уехал с семьёй в Курган. Стал и там душой клуба горных туристов. С его подачи началась тесная дружба Томской и Курганской команд, участвующих во Всесоюзных и Всероссийских соревнованиях по технике горного туризма. Саша был капитаном команды. Ходил и водил сложные горные походы, сплавлялся на байдарках. В 1982 году поход 5к.с. под его руководством занял 1 место в Чемпионате ДСО \"Зенит\". Саша получил звание \"Мастер спорта СССР\". В 1992г. совершил восхождение на пик Ленина. В 1997 году Шалаевы вернулись в Томск.</p>\r\n<p>Тяжёлая болезнь... 19 февраля 1999 года Саши не стало. О нем остались фильмы, фотографии и наша добрая память.</p>','http://inmemoria.tusur.ru/media/20120908161445.jpg','http://inmemoria.tusur.ru/media/20120908161445s.jpg',1),(33,'card18.tpl','Леонид','Спиридонов','','Кузьмич','','0000-00-00','1973-08-04','<p>Спиридонов Леонид Кузьмич. Окончил Томский политехнический институт. Стоял у истоков Томского альпинизма. Мастер спорта СССР и Чемпион Союза по альпинизму.</p>\r\n<p>4 августа 1973г. в рамках восхождения на пик Революции, на леднике Федченко (5100м.) по природным и медицинским причинам заболел и после двухдневной транспортировки умер</p>','http://inmemoria.tusur.ru/media/20120906220249.jpg','http://inmemoria.tusur.ru/media/20120906220249s.jpg',1),(34,'card5.tpl','Сергей','Чесноков','','Михайлович','','1947-12-17','1997-01-01','<p>Чесноков Сергей Михайлович родился 17 декабря 1947г. в г.Белово Кемеровской области. В 1971г. окончил ФЭТиА ТИРиЭТ. В последние годы работал заведующим лабораторией в Республиканском инженерно-техническом центре.</p>\r\n<p>Спортивным туризмом начал заниматься в Томске в 1966 г. Районы походов: Восточный, Западный Саян, Горный Алтай, Бурятия, Хамар-Дабан, Кемеровская область, Тянь-Шань и др. Прошел участником и руководителем 39 водных маршрутов, из них 16 &ndash; V-VI категории сложности, по рекам: Иман, Агул, Уда, Верх. Катунь, Ципа, Башкаус, Аргут, Чуя (Мажойский каскад), Чулышман, Китой, Кантегир, Енисей, Хара-Мурин, Утулик, Иркут, Ара-Хобуты, Ара-Ошей, Шумак, Оя, Чарын и другим. Его тренером-наставником был Л.Фомин.</p>\r\n<p>Босс отделения ФЭТ в 1968-69гг, Обладатель жетона \"Ветеран ТАКТ\" 3 степени, Мастер спорта с 1977г.</p>\r\n<p>Инструкторская подготовка и работа: всесоюзный семинар по водному туризму (г. Кишинев); всесоюзные сборы КСС (г. Иркутск, т/б &ldquo;Утулик&rdquo;); зональные совещания МКК по проблемам безопасности (г. Новосибирск); школы СТП, ВТП (г. Томск); лектор на семинарах и на факультете общественных профессий (отделение водного туризма) при Томском политехническом университете. Старший инструктор водного туризма.</p>\r\n<p>Сергей Чесноков был одним из лидеров томского туризма. Он воспитал несколько поколений туристов-водников. Наверное, любимой его рекой был Китой, где он был несколько раз и участвовал во всех первопрохождениях реки и ее притоков. Туристы Томска предлагают назвать участок р. Билюты (приток Китоя) ниже 16-метрового водопада каньоном Чеснокова. Каньон не имеет именного названия и при первопрохождении его в 1988 г. при участии С.М.Чеснокова фигурировал как нижний каньон.&nbsp;</p>\r\n<p>В 1991г. возглавил Общественный совет при детско-юношеском туристском клубе &laquo;Арба&raquo;. Ему же принадлежит идея организации конференции по водному туризму. Сергей собрал многочисленную команду Томичей, друзей из Новосибирска, Барнаула, Алтайского края. Это была его задумка, душевный порыв, который поддержали единомышленники. Самая первая конференция прошла в декабре 1996г в турклубе &laquo;Арба&raquo; и с тех пор она стала ежегодной.</p>\r\n<p>Сергей Чесноков ушел из жизни в 1997г</p>','http://inmemoria.tusur.ru/media/20120907125135.jpg','http://inmemoria.tusur.ru/media/20120907125135s.jpg',1),(36,'card10.tpl','Сергей','Гусельников','','Геннадьевич','ЧС','1967-12-23','2006-08-26','<p>Гусельников Сергей Геннадьевич родился 23 декабря 1967г.</p>\r\n<p>Босс ФЭТа в 1992-94гг. Спелеолог, много ходил сам и активно водил народ. Наверное, каждый, ходивший в пещеры в то время, может сказать: \"Меня водил Серега Гусельников\"</p>\r\n<p>Сергей&nbsp;скончался 26 августа 2006г. в результате сердечного приступа.</p>','http://inmemoria.tusur.ru/media/20120910224755.jpg','http://inmemoria.tusur.ru/media/20120910224755s.jpg',1),(37,'card3.tpl','Игорь','Левкин','','Анатольевич','','1964-04-05','2007-06-08','<p>Левкин Игорь Анатольевич родился 5 апреля 1964г. Алтайский парапланерист и водник. Установил в районе высокогорной Чуйской степи абсолютный рекорд России, поднявшись на параплане на высоту 5200 метров. Первый кандидат в мастера спорта по парапланерному спорту в Сибири. Первый со своим напарником, кто спустился с горы Белуха на параплане.</p>\r\n<p>8 июня 2007г. Игорь погиб в аварии на трассе Новосибирск - Бийск - Ташанта. У него остались жена и взрослая дочь.</p>','http://inmemoria.tusur.ru/media/20120911225109.jpg','http://inmemoria.tusur.ru/media/20120911225109s.jpg',1),(38,'card4.tpl','Болеслав','Цой','','Григорьевич','Славка','1952-02-24','1997-08-05','<p>Цой Болеслав Григорьевич родился 24 февраля 1952г.&nbsp;приехал в Томск из Андижана в 1969г. После окончания института&nbsp;работал в Томском конструкторском бюро ПРОЕКТ до 1980г.&nbsp;После чего перешёл работать в Специальное конструкторско-технологическое бюро геофизической техники, (СКТБ ГТ), впоследствии переименованном в фирму ГЕОФИТ. &nbsp;Там работал до 1995 года. Потом &nbsp;занимался коммерческой деятельностью. В ТАКТЕ откликался на \"Славку\" или \"Славуня\".&nbsp;Был женат, &nbsp;две дочери, два внука.</p>\r\n<p>Погиб 5 августа 1997г.</p>','http://inmemoria.tusur.ru/media/20120913171857.jpg','http://inmemoria.tusur.ru/media/20120913171857s.jpg',1),(39,'card3.tpl','Алексей','Хныкин','','Иванович','Хнык','1966-05-15','2009-07-26','<p>Хныкин Алексей Иванович родился 15 мая 1966 года в г.Райчихинск Амурской области.<br />В Томск приехал в 1983 году - поступать в ТИАСУР. Поступил и ..... учился<br />там много много лет! За время учебы он успел сходить в армию, жениться и даже \"родить\" двух сыновей.<br />Много лет он проработал в СЧ №16 пожарным-спасателем. Его не стало 26.07.2009г. в результате тяжелой болезни.</p>','http://inmemoria.tusur.ru/media/20120912155521.jpg','http://inmemoria.tusur.ru/media/20120912155521s.jpg',1),(40,'card7.tpl','Дмитрий','Межевой','','Станиславович','','1957-05-10','1993-05-10','<p>Родился 10 мая 1957 года.<br />Приехал в Томск и учился в ТИАСУРе на КТФ с 1975 по 1980г.<br />Ходил в походы, был участником и руководителем.<br />После окончания ТИАСУРа работал в Институте оптики и атмосферы.<br />Женился в 1982 году на Елецкой Ирине. Замечательный семьянин.<br />В 1984 году родилась дочь Женя, в 1986 - дочь Тоня.<br />Умер 10 мая 1993г. (онкология).<br />Дочь Тоня продолжает начатые родителями традиции. <br />Занимается альпинизмом, туризмом и скалолазанием.<strong><br /><br /><br /></strong></p>','http://inmemoria.tusur.ru/media/20120913145343.jpg','http://inmemoria.tusur.ru/media/20120913145343s.jpg',1),(41,'card20.tpl','Сергей','Кужелев','','Михайлович','','1946-09-01','1991-01-09','<p>Кужелев Сергей Михайлович родидся 1 сентября 1946г. в пос.Каргасок Томской &nbsp;области. После окончания школы поступил в ТИРиЭТ, КТФ. Был активным членом ТАКТа.&nbsp;После окончания института (ТИРиЭТ) работал в лаборатории \"Роста кристаллов\" при кафедре СВЧ. Годы в клубе: 1967-1970.</p>\r\n<p>Умер 9 января 1991г.</p>','http://inmemoria.tusur.ru/media/20120913173555.jpg','http://inmemoria.tusur.ru/media/20120913173555s.jpg',1),(42,'card6.tpl','Михаил','Чмых','','Кириллович','','1938-01-01','1999-01-01','<p>Чмых Михаил Кириллович родился в 1938г. Окончил Томский Политехнический Институт. Впоследствии жил и работал в Красноярске. Доктор технических наук, профессор КГТУ,заведующий кафедрой радиотехники, член-корреспондент МАН ВШ, заслуженный изобретатель России. Создал при Красноярском политехническом научную лабораторию цифровой фазометрии, которая занималась созданием отечественных цифровых фазоизмерительных приборов. Разработал также государственный эталон фазы &mdash; один из фазометров Чмыха сегодня находится в палате меры весов в Пулково. У Михаила Кирилловича &mdash; более 200 изобретений! 10 декабря 1998 года указом президента Российской Федерации Чмыху Михаилу Кирилловичу присуждена награда \"ЗАСЛУЖЕННЫЙ РАБОТНИК ВЫСШЕЙ ШКОЛЫ РОССИЙСКОЙ ФЕДЕРАЦИИ\" <a href=\"http://www.lawmix.ru/pprf.php?id=135150%20\" target=\"_blank\">http://www.lawmix.ru/pprf.php?id=135150&nbsp;</a></p>\r\n<p>Михаил Кириллович скончался в 1999г.</p>','http://inmemoria.tusur.ru/media/20120913175753.jpg','http://inmemoria.tusur.ru/media/20120913175753s.jpg',1),(43,'card1.tpl','Ольга','Кужелева','Прахт','Давыдовна','','1949-04-23','1993-06-07','<p>Кужелева (Прахт) Ольга Давыдовна родилась 23 апреля 1949 г.в г. Белово Кемеровской обл.В 1966 г. закончила Бочатскую среднюю школу, поступила в ТИРиЭТ на КТФ. Этой же осенью пришла в ТАКТ и все время учебы была активной участницой всех событий клуба. В 1971 г. вышла замуж за Сергея Кужелева. У них родилось двое сыновей Леонид и Евгений.</p>\r\n<p>Умерла 07 июля 1993 г.&nbsp;</p>\r\n<div>&nbsp;</div>','http://inmemoria.tusur.ru/media/20120919154826.jpg','http://inmemoria.tusur.ru/media/20120919154826s.jpg',1),(44,'card2.tpl','Надежда','Лагздынь','','Юрьевна','','0000-00-00','1993-01-01','<p>годы в клубе 1968-1973</p>\r\n<p>Умерла летом 1993г.</p>','http://inmemoria.tusur.ru/media/20120915232108.jpg','http://inmemoria.tusur.ru/media/20120915232108s.jpg',1),(45,'card15.tpl','Алексей','Иващенко','','Сергеевич','','1950-01-01','2012-03-10','<p>Иващенко Алексей Сергеевич родился в 1950г. В 1973г. окончил ТИАСУР, КТФ. Босс отделения КТФ в 1970-71гг. Обладатель жетона \"Ветеран ТАКТ\" третьей степени. По распределению уехал в г.Миасс.&nbsp;Алексей Сергеевич внес большой вклад в развитие спортивного скалолазания&nbsp;в Миасском городском округе. Около 20 лет он тренировал детей, им были подготовлены 3 мастера&nbsp;спорта, победители и призеры этапов Кубка Европы, Чемпионка мира. Тренажеры искусственного рельефа в&nbsp;ДС &laquo;Заря&raquo;, на которых занимаются сейчас будущие чемпионы, спроектированы и построены при его&nbsp;непосредственном участии.</p>\r\n<p>Мастер спорта, Чемпион&nbsp;СССР и РФ по альпинизму, тренер по спортивному скалолазанию и туризму.</p>\r\n<p>Ушел из жизни 10 марта 2012г.</p>','http://inmemoria.tusur.ru/media/20120924144810.jpg','http://inmemoria.tusur.ru/media/20120924144810s.jpg',1),(46,'card2.tpl','Сергей','Харитонов','','Петрович','','1969-02-23','1996-08-04','<p>Харитонов Сергей Петрович родился 23 февраля 1969 года. В 1986г. окончил среднюю школу &nbsp;№2 города Нефтегорска. &nbsp;Поступил в ТИРиЭТ в 1987 году, после первого курса &nbsp;служил в армии, войска ПВО в городе Минске. Вернулся в институт в 1990 году. В ТАКТ пришел после возвращения из армии в 1990 году. &nbsp;Успел сходить в три похода.</p>\r\n<p>Погиб &nbsp; 04 августа &nbsp;1996 года.</p>\r\n<div>&nbsp;</div>','http://inmemoria.tusur.ru/media/20120924173247.jpg','http://inmemoria.tusur.ru/media/20120924173247s.jpg',1),(47,'card1.tpl','Юрий','Тышкевич','','Анатольевич','','1948-06-07','1994-07-10','<p>Тышкевич Юрий Анатольевич родился 07 июня &nbsp;1948 в с.Пудино в семье сельских учителей. &nbsp;В 1967 году поступил в Томский Институт Радиоэлектроники и Электронной Техники (ТИРЭТ) на факультет РТФ (27 группа). Окончил институт в 1973 году. Служил в армии в Монголии. В 1975 году женился. &nbsp;Работал в Новосибирске, потом вернулся на постоянное проживание в с.Тогур &nbsp;Колпашевского района. Работал старшим инженером ЗапСибАэронавигации в Авиапредприятии г. Колпашево. &nbsp;Имеет двух дочерей. &nbsp;Погиб &nbsp;10 июля 1994 г на реке Кеть спасая двух утопающих детей. Детей спас.</p>\r\n<div>&nbsp;</div>','http://inmemoria.tusur.ru/media/20120919144652.jpg','http://inmemoria.tusur.ru/media/20120919144652s.jpg',1),(48,'card11.tpl','Светлана','Перегудова','Васильева','Геннадьевна','','1979-11-22','2004-05-08','<p>Перегудова (Васильева) Светлана Геннадьевна родилась 22 ноября 1979 года в Москве. Училась в г. Серпухове, там же начала заниматься в клубе туристов &laquo;Путник&raquo;. До поступления на медицинский факультет академии Маймонида в Москве выполнила второй спортивный разряд по горному туризму, занималась спортивным ориентированием, водным и пешеходным туризмом, побывала на Дальнем Востоке, Камчатке, Байкале, в Забайкалье, Карелии. Участник и неоднократный победитель и призер городских, областных и республиканских соревнований по технике горного туризма.&nbsp;</p>\r\n<p>Во время учебы в академии активно ходила в горы с туристами МГУ. Выполнила норматив первого спортивного разряда по горному туризму. Большая часть горных маршрутов, которые она ходила &ndash; по Кавказу, Тянь-Шаню. Имеет опыт участия в походах четвертой категории и руководства походами третьей категории.&nbsp;</p>\r\n<p>В 2003 году с отличием закончила академию. В этом же году родила дочь, а на следующий 2004 год поступила учиться в аспирантуру по направлению &laquo;остеопатия&raquo;.&nbsp;</p>\r\n<p>&nbsp; Летом 2004 года планировала руководить походом четвертой категории по Центральному Кавказу, а в начале мая повела небольшую группу туристов в тренировочный поход на Кавказ.</p>\r\n<p>&nbsp;8 мая при спуске с перевала Софийское седло группу накрыла лавина. Света погибла. Остальные живы.</p>','http://inmemoria.tusur.ru/media/20120924173135.jpg','http://inmemoria.tusur.ru/media/20120924173135s.jpg',1),(51,'card8.tpl','Валентина','Капилевич','Орлова','Дмитриевна','','1942-11-13','2009-05-15','<p>Капилевич Валентина Дмитриевна (в девичестве Орлова) родилась 13 ноября 1942г. Начинала учиться в ТПИ, закончила уже ТИРиЭТ в 1966г. В походы начала ходить с первого курса (Памир, Горная Шория, Камчатка, Тыва)</p>\r\n<p>Валентины не стало 15 мая 2009г</p>','http://inmemoria.tusur.ru/media/20121120214154.jpg','http://inmemoria.tusur.ru/media/20121120214154s.jpg',1),(49,'card20.tpl','Владимир','Третьяков','','Александрович','','1968-09-26','1992-11-30','<p>Родился в г.Каменск-Уральский 26.09.1968. Учился в ТИАСУРе (КТФ). Женился в 1989г., с женой уехал в Томск. Там у них родился сын. Погиб Володя в 1992 году&nbsp; в результате несчастного случая во время работ по сбору кедрового ореха (п.Заварзино).<br /><br /><br /></p>','http://inmemoria.tusur.ru/media/20121003182950.jpg','http://inmemoria.tusur.ru/media/20121003182950s.jpg',1),(50,'card19.tpl','Людмила','Доботкина','Корнющенко','Владимировна','Люси','1965-08-20','2005-06-21','<p>Людмила Владимировна Доботкина&nbsp;(девичья фамилия -&nbsp;Корнющенко).</p>\r\n<p>Родилась 20.08.1965 г., ушла из жизни 21.06.2005 г.</p>\r\n<p>Новичок 1983 года на факультете ФСУ. Ходила в горные походы, занималась альпинизмом, в лыжные походы. Была на Киргизском, Заилийском хребтах, Фанских горах.</p>','http://inmemoria.tusur.ru/media/20121029084951.jpg','http://inmemoria.tusur.ru/media/20121029084951s.jpg',1),(52,'card3.tpl','Леонид','Капилевич','','Семенович','','1937-07-07','2012-07-10','<p>Капилевич Леонид Семенович родился 7 июля 1937г. Начинал учиться в ТПИ, окончил ТИРиЭТ в 1967г.</p>\r\n<p>Леонид ушел из жизни 10 июля 2012г.</p>','http://inmemoria.tusur.ru/media/20121213192204.jpg','http://inmemoria.tusur.ru/media/20121213192204s.jpg',1),(53,'card8.tpl','Анатолий','Молодежников','','Михайлович','Молодой','1938-02-13','2014-04-02','<p><span style=\"font-size: small;\">Молодежников Анатолий Михайлович родился 13 февраля 1938г.</span></p>\r\n<p><span style=\"font-size: small;\">В 1961г окончил РТФ ТПИ. Уже в те годы проводил большую работу по организации туристских походов в политехническом институте.</span></p>\r\n<p><span style=\"font-size: small;\">Основатель клуба ТАКТ в 1962г. Обладатель жетона \"Ветеран ТАКТ\" 1 степени №1. КМС по альпинизму, 1 спортивный разряд по горному туризму,&nbsp;инструктор по альпинизму, инструктор - методист по туризму, судья второй категории, член всесоюзного спасотряда (жетон №885).&nbsp;Кандидат технических наук, доцент ТУСУРа, в последние годы жизни - проректор ТУСУРа.</span></p>\r\n<p><span style=\"font-size: small;\">За этими официальными словами стоит Учитель, Наставник, Основатель нашего клуба, который живет и действует более 50 лет, клуба который знают&nbsp;все, кто ходит в горы на планете Земля. Человек, подаривший не одной сотне молодых ребят и девчат образ жизни, давший радость общения, научивший&nbsp;побеждать и делать выводы из поражений, определивший судьбы и спортивные и личные.</span></p>\r\n<p><span style=\"font-size: small;\">Анатолий Михайлович ушел из жизни 2 апреля 2014г.</span></p>','http://inmemoria.tusur.ru/media/20140512160615.jpg','http://inmemoria.tusur.ru/media/20140512160615s.jpg',1);
/*!40000 ALTER TABLE `person` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `resource`
--

DROP TABLE IF EXISTS `resource`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `resource` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `person_id` int(11) NOT NULL COMMENT 'Идентификатор человека',
  `name` varchar(50) NOT NULL COMMENT 'Наименование резурса, для списка ресурсов',
  `type` enum('img','video','audio','url','text','html','doc') NOT NULL COMMENT 'Тип ресурса',
  `rubric` enum('gallery','memoir','hike') NOT NULL COMMENT 'Рубрика',
  `data` text NOT NULL COMMENT 'Сам рерурс, тектс, или ссылка, или html',
  `position` smallint(6) NOT NULL DEFAULT '0' COMMENT 'Позиция, для сортировки',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Время последней модификации',
  `comment` text NOT NULL COMMENT 'Подпись к ресурсу',
  `active` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'Признак активности',
  PRIMARY KEY (`id`),
  KEY `id` (`id`,`person_id`)
) ENGINE=MyISAM AUTO_INCREMENT=842 DEFAULT CHARSET=cp1251 COMMENT='Таблица данных';
/*!40101 SET character_set_client = @saved_cs_client */;

